import React, { useMemo, useState } from "react";
import { useAppState } from "../context/AppContext";

const researchPipelineSteps = [
  {
    key: "extract",
    title: "1. Text Extraction",
    text: "Raw document text is pulled from PDF, DOCX, or TXT using format-specific parsers.",
    icon: "📄",
  },
  {
    key: "normalize",
    title: "2. Text Normalization",
    text: "Unicode accent stripping and lowercasing match exact research pre-processing.",
    icon: "🧹",
  },
  {
    key: "tfidf",
    title: "3. 100k TF-IDF Vectorization",
    text: "Transformed via fitted 100,000 unigram/bigram vocabulary with sublinear term frequency.",
    icon: "📊",
  },
  {
    key: "svc",
    title: "4. LinearSVC Decision Scoring",
    text: "Signed distance to each class-separating hyperplane is calculated via decision_function().",
    icon: "⚖️",
  },
  {
    key: "margin",
    title: "5. Decision Margin & Uncertainty",
    text: "Margin between top-1 and top-2 hyperplane scores dictates operational confidence tier.",
    icon: "📐",
  },
  {
    key: "xai",
    title: "6. Linear Feature Attribution",
    text: "Exact token contribution (x_j * w_c,j) surfaces the strongest lexical drivers without black-box drift.",
    icon: "🔍",
  },
  {
    key: "sort",
    title: "7. Automated Desktop Sorting",
    text: "Files are organized into ~/Desktop/SortedDocuments/<Category> (or staged in _pending if ambiguous).",
    icon: "📁",
  },
];

function folderLabelFromPath(storedPath) {
  if (!storedPath || typeof storedPath !== "string") return "—";
  const parts = storedPath.split(/[/\\]/).filter(Boolean);
  if (parts.length < 2) return parts[0] || "—";
  return parts[parts.length - 2];
}

function fileNameOnly(name) {
  if (!name) return "—";
  const parts = String(name).split(/[/\\]/);
  return parts[parts.length - 1] || name;
}

function ResultDashboard({ result, theme, onUploadAnother, onBackHome }) {
  const { confirmManualSort, domainPalette } = useAppState();
  const [choiceError, setChoiceError] = useState("");
  const [choiceBusy, setChoiceBusy] = useState(false);
  const [scoresExpanded, setScoresExpanded] = useState(true);

  const decisionMargin =
    result?.decisionMargin != null && !Number.isNaN(Number(result.decisionMargin))
      ? Number(result.decisionMargin)
      : null;

  const uncertaintyLevel =
    result?.uncertaintyLevel ||
    (decisionMargin != null
      ? decisionMargin >= 1.0
        ? "High confidence"
        : decisionMargin >= 0.5
        ? "Moderate confidence"
        : "Ambiguous"
      : "Moderate confidence");

  const isAmbiguous =
    uncertaintyLevel.toLowerCase().includes("ambiguous") ||
    (decisionMargin != null && decisionMargin < 0.5);

  const needsChoice = Boolean(result?.requiresManualChoice && result?.pendingId);
  const candidates = Array.isArray(result?.topTwoDomains) ? result.topTwoDomains : [];

  const keywords = useMemo(() => {
    const raw = result?.keywords && result.keywords.length ? result.keywords : result?.fallbackKeywords || [];
    return raw.slice(0, 14);
  }, [result]);

  const folderName = useMemo(() => folderLabelFromPath(result?.storedIn), [result?.storedIn]);

  // Decision scores list sorted descending
  const sortedScores = useMemo(() => {
    const rawScores = result?.decisionScores || {};
    return Object.entries(rawScores)
      .map(([cls, val]) => ({
        className: cls,
        score: typeof val === "number" ? val : parseFloat(val) || 0.0,
      }))
      .sort((a, b) => b.score - a.score);
  }, [result?.decisionScores]);

  const handlePickDomain = async (domain) => {
    setChoiceError("");
    setChoiceBusy(true);
    try {
      await confirmManualSort(result.pendingId, domain);
    } catch (e) {
      setChoiceError(e?.message || "Could not move the file.");
    } finally {
      setChoiceBusy(false);
    }
  };

  if (result?.error || result?.isBlank) {
    return (
      <div className="resultDashboard resultDashboard--blank">
        <div className="validationErrorCard cardRise" role="alert">
          <div className="validationErrorCard__icon" aria-hidden="true">⚠️</div>
          <span className="eyebrow eyebrow--warning">Validation Notice</span>
          <h2>Document Content Rejected</h2>
          <p className="validationErrorCard__message">
            {result.error || "This document appears to be blank or contains no readable text. Please upload a document with readable content."}
          </p>
          <p className="validationErrorCard__details">
            File: <strong>{result.filename || "Uploaded document"}</strong> — No readable text was detected. The document was not submitted to the machine learning classifier and was not sorted into any folder.
          </p>
          <div className="resultDashboard__actions" style={{ marginTop: "24px" }}>
            <button className="button button--primary" type="button" onClick={onUploadAnother}>
              Upload Another File
            </button>
            <button className="button button--secondary" type="button" onClick={onBackHome}>
              Back to Home
            </button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="resultDashboard">
      {/* HERO CARD */}
      <article
        className="resultHeroCard cardRise"
        style={{ "--accent": theme.color, "--accentSoft": theme.soft, "--accentBorder": theme.border }}
      >
        <div className="resultHeroCard__glow" aria-hidden="true" />
        <div className="resultHeroCard__inner">
          <div className="resultHeroCard__top">
            <span className="eyebrow">Research LinearSVC (C=0.5)</span>
            <span className="resultPill resultPill--large">{theme.label}</span>
            {needsChoice ? (
              <span className="resultHeroCard__success resultHeroCard__success--pending">
                <span className="resultHeroCard__successDot" aria-hidden="true" />
                Ambiguous margin — manual review recommended
              </span>
            ) : (
              <span className="resultHeroCard__success">
                <span className="resultHeroCard__successDot" aria-hidden="true" />
                Success — file organized automatically
              </span>
            )}
          </div>

          <p className="resultHeroCard__domainLabel">Predicted category</p>
          <h2 className="resultHeroCard__domainTitle">{result.prediction}</h2>

          <div className="resultHeroMetaGrid">
            <div className="resultHeroMeta">
              <span>File name</span>
              <strong title={result.filename}>{fileNameOnly(result.filename)}</strong>
            </div>
            <div className="resultHeroMeta">
              <span>File type</span>
              <strong>{result.fileType}</strong>
            </div>
            <div className="resultHeroMeta">
              <span>Decision Margin</span>
              <strong>{decisionMargin != null ? decisionMargin.toFixed(2) : "—"}</strong>
            </div>
            <div className="resultHeroMeta">
              <span>Uncertainty Level</span>
              <strong>{uncertaintyLevel}</strong>
            </div>
          </div>
        </div>
      </article>

      {/* CONFIDENCE & DECISION MARGIN PANEL */}
      <section className="confidencePanel cardRise">
        <div className="confidencePanel__head">
          <span className="eyebrow">Model Decision Certainty</span>
          <div className="confidencePanel__pctRow">
            <strong className="confidencePanel__pct">
              {decisionMargin != null ? decisionMargin.toFixed(2) : "—"}
            </strong>
            <span
              className={`confidencePanel__label ${
                isAmbiguous ? "confidencePanel__label--ambiguous" : "confidencePanel__label--confident"
              }`}
            >
              {isAmbiguous ? "Ambiguous — manual review recommended" : uncertaintyLevel}
            </span>
          </div>
        </div>

        {/* Visual Decision Margin Meter */}
        <div className="marginMeterWrap" aria-label="Decision Margin Meter">
          <div
            className="marginMeter__bar"
            style={{
              width: `${Math.min(100, Math.max(12, ((decisionMargin || 0) / 3.0) * 100))}%`,
              background: isAmbiguous
                ? "linear-gradient(90deg, #f59e0b, #ef4444)"
                : `linear-gradient(90deg, var(--teal), ${theme.color})`,
            }}
          />
        </div>

        <div className="marginScaleLegend">
          <span>0.0 (Boundary)</span>
          <span>0.5 (Moderate)</span>
          <span>1.0+ (High Separation)</span>
        </div>

        <p className="confidencePanel__hint">
          {needsChoice
            ? "Decision margin between top-1 and runner-up is below 0.50. Select one of the two closest categories below to finalize folder sorting."
            : "Decision margin represents the separation between highest and second-highest LinearSVC hyperplane scores (top - second). These are operational decision-margin thresholds, not calibrated probabilities."}
        </p>
      </section>

      {/* EXPANDABLE MODEL DECISION SCORES SECTION */}
      <section className="decisionScoresPanel cardRise">
        <div
          className="decisionScoresPanel__header"
          onClick={() => setScoresExpanded((prev) => !prev)}
          role="button"
          tabIndex={0}
          onKeyDown={(e) => {
            if (e.key === "Enter" || e.key === " ") setScoresExpanded((prev) => !prev);
          }}
        >
          <div className="decisionScoresPanel__titleWrap">
            <span className="eyebrow">Hyperplane Distances</span>
            <h3>Model Decision Scores</h3>
          </div>
          <button
            type="button"
            className="button button--secondary button--compact"
            aria-expanded={scoresExpanded}
          >
            {scoresExpanded ? "Hide Breakdown ▲" : "Show Breakdown ▼"}
          </button>
        </div>

        {scoresExpanded && (
          <div className="decisionScoresPanel__body">
            <p className="decisionScoresPanel__disclaimer">
              Values represent signed distances to class-separating hyperplanes produced by{" "}
              <strong>LinearSVC (C=0.5)</strong>. Positive values indicate support for the category; negative
              values indicate opposition. These are uncalibrated decision scores, not probabilities.
            </p>

            <div className="decisionScoresTable">
              {sortedScores.map((item, index) => {
                const pal = domainPalette[item.className] || domainPalette.Unknown;
                const isTop = index === 0;
                const isSecond = index === 1;
                return (
                  <div
                    key={item.className}
                    className={`decisionScoreRow ${isTop ? "decisionScoreRow--top" : ""}`}
                    style={{ "--rowAccent": pal.color }}
                  >
                    <div className="decisionScoreRow__info">
                      <span className="decisionScoreRow__rank">#{index + 1}</span>
                      <span className="decisionScoreRow__name">{item.className}</span>
                      {isTop && <span className="decisionScoreRow__tag">Predicted</span>}
                      {isSecond && <span className="decisionScoreRow__tag decisionScoreRow__tag--runner">Runner-up</span>}
                    </div>
                    <div className="decisionScoreRow__scoreWrap">
                      <span
                        className={`decisionScoreRow__val ${
                          item.score >= 0 ? "decisionScoreRow__val--pos" : "decisionScoreRow__val--neg"
                        }`}
                      >
                        {item.score >= 0 ? `+${item.score.toFixed(4)}` : item.score.toFixed(4)}
                      </span>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        )}
      </section>

      {/* AMBIGUOUS RESOLUTION SECTION */}
      {needsChoice && candidates.length > 0 && (
        <section className="domainChoiceSection cardRise" aria-labelledby="domain-choice-heading">
          <div className="domainChoiceSection__head">
            <span className="eyebrow">Manual Review Required</span>
            <h3 id="domain-choice-heading">Which folder should this document use?</h3>
            <p className="domainChoiceSection__sub">
              The model detected overlapping vocabulary between the top two categories (margin &lt; 0.50).
              Choose your intended destination folder.
            </p>
          </div>
          {choiceError ? <p className="domainChoiceSection__error">{choiceError}</p> : null}
          <div className="domainChoiceGrid">
            {candidates.map((row, idx) => {
              const label = String(row.domain || "").trim();
              const pal = domainPalette[label] || domainPalette.Unknown;
              const scoreVal =
                row.score != null && !Number.isNaN(Number(row.score))
                  ? Number(row.score).toFixed(2)
                  : "—";
              return (
                <article
                  key={`${label}-${idx}`}
                  className="domainChoiceCard cardRise"
                  style={{
                    "--accent": pal.color,
                    "--accentSoft": pal.soft,
                    "--accentBorder": pal.border,
                  }}
                >
                  <span className="domainChoiceCard__label">{pal.label}</span>
                  <p className="domainChoiceCard__pct">Score: {scoreVal}</p>
                  <p className="domainChoiceCard__hint">LinearSVC decision score</p>
                  <button
                    type="button"
                    className="button button--primary domainChoiceCard__btn"
                    disabled={choiceBusy}
                    onClick={() => handlePickDomain(label)}
                  >
                    {choiceBusy ? "Sorting…" : `Sort into ${pal.label}`}
                  </button>
                </article>
              );
            })}
          </div>
        </section>
      )}

      {/* LOCAL STORAGE */}
      <section className="storagePremium cardRise">
        <div className="storagePremium__iconWrap" aria-hidden="true">
          <span className="storagePremium__folderIcon">📂</span>
        </div>
        <div className="storagePremium__body">
          <span className="eyebrow">Local storage</span>
          <h3 className="storagePremium__title">
            {needsChoice ? "File waiting in pending review queue" : "Document successfully sorted into"}
          </h3>
          <div className="storagePremium__folderRow">
            <span className="storagePremium__folderName">
              {needsChoice ? "SortedDocuments / _pending" : folderName}
            </span>
            {!needsChoice ? <span className="resultPill storagePremium__domainPill">{theme.label}</span> : null}
          </div>
          <p className="storagePremium__pathLabel">{needsChoice ? "Status" : "Full path"}</p>
          <code className="storagePremium__path">
            {needsChoice
              ? "Choose a domain above to move the file out of the pending folder into the correct category on disk."
              : result.storedIn || "No path returned by the backend."}
          </code>
        </div>
      </section>

      {/* LEXICAL FEATURE ATTRIBUTION */}
      <section className="keywordPanel cardRise">
        <div className="keywordPanel__head">
          <span className="eyebrow">Linear Feature Attribution</span>
          <h3>Influential Lexical Features</h3>
          <p className="keywordPanel__sub">
            Terms with the strongest positive contribution (x_j · w_c,j) to the predicted class decision score,
            computed from document TF-IDF values and LinearSVC weights.
          </p>
        </div>
        <div className="keywordChipRow">
          {keywords.map((word, idx) => (
            <span key={`${word}-${idx}`} className="keywordChip">
              {word}
            </span>
          ))}
        </div>
      </section>

      {/* REASONING & INTERPRETABILITY */}
      <section className="reasoningPanel cardRise">
        <span className="eyebrow">Interpretability</span>
        <h3>Decision Explanation</h3>
        <p className="reasoningPanel__lead">{result.detailedReasoning}</p>
        <div className="reasoningPanel__grid">
          <div className="reasoningSubCard">
            <h4>Textual patterns</h4>
            <p>{result.patternNote}</p>
          </div>
          <div className="reasoningSubCard">
            <h4>TF‑IDF weighting</h4>
            <p>{result.tfidfNote}</p>
          </div>
          <div className="reasoningSubCard">
            <h4>LinearSVC decision</h4>
            <p>{result.nbNote}</p>
          </div>
        </div>
      </section>

      {/* SUMMARY */}
      <section className="aiSummaryPanel cardRise">
        <span className="eyebrow">Document Summary</span>
        <h3>Analysis Overview</h3>
        <p>{result.aiSummary}</p>
      </section>

      {/* MACHINE LEARNING PIPELINE */}
      <section className="miningPanel cardRise">
        <div className="miningPanel__head">
          <span className="eyebrow">Research Pipeline</span>
          <h3>Machine Learning Operations</h3>
          <p>End-to-end preprocessing, feature weighting, and classification steps applied to your upload.</p>
        </div>
        <div className="miningGrid">
          {researchPipelineSteps.map((op) => (
            <article key={op.key} className="miningCard cardRise">
              <span className="miningCard__icon" aria-hidden="true">
                {op.icon}
              </span>
              <h4>{op.title}</h4>
              <p>{op.text}</p>
            </article>
          ))}
        </div>
      </section>

      {/* ACTIONS */}
      <div className="resultDashboard__actions">
        <button className="button button--primary" type="button" onClick={onUploadAnother}>
          Upload Another File
        </button>
        <button className="button button--secondary" type="button" onClick={onBackHome}>
          Back to Home
        </button>
      </div>
    </div>
  );
}

export default ResultDashboard;
